front:
server {
	listen 443 ssl;
	ssl_certificate     /etc/nginx/tls/192.168.205.1.crt;
	ssl_certificate_key /etc/nginx/tls/192.168.205.1.key;
	resolver 127.0.0.11 ipv6=off valid=30s;
	proxy_http_version 1.1;
	proxy_buffering off;

	if ($request_method !~ ^(GET|HEAD)$) {
		return 405;
	}

	location = /v2/ {
		default_type application/json;
		add_header Docker-Distribution-API-Version registry/2.0 always;
		return 200 '{}';
	}

	location /v2/docker-registry.kixdesk.com/ {
		set $vendor_backend vendor-docker-registry-kixdesk-com:5000;
		rewrite ^/v2/docker\-registry\.kixdesk\.com/(.*)$ /v2/$1 break;
		proxy_pass http://$vendor_backend;
	}

	location /v2/ghcr.io/ {
		set $vendor_backend vendor-ghcr-io:5000;
		rewrite ^/v2/ghcr\.io/(.*)$ /v2/$1 break;
		proxy_pass http://$vendor_backend;
	}

	location /v2/mcr.microsoft.com/ {
		set $vendor_backend vendor-mcr-microsoft-com:5000;
		rewrite ^/v2/mcr\.microsoft\.com/(.*)$ /v2/$1 break;
		proxy_pass http://$vendor_backend;
	}

	location / {
		return 404;
	}
}
